#!/bin/sh
# test_qconf.sh — qconf 2.5 test_package 驱动（R34：实质执行被测包二进制）
#
# 用法: sh test_qconf.sh <qconf_bin_dir> [work_dir]
#   work_dir 缺省时回退到 ${TMPDIR:-/tmp}/qconf-test-$$（不污染配方目录）
# 断言：
#   TC-01 qconf --version 输出 "qconf version"
#   TC-02 qconf --help 输出用法
#   TC-03 用 .qc 生成 configure 成功
#   TC-04 configure 含 "Generated by qconf" 生成标记
#   TC-05 configure 含 "conf4"（Qt5 运行期构建逻辑已嵌入）
#   TC-06 【鸿蒙特有】qconf 为 OHOS aarch64 ELF（e_machine=0xB7）且可在本机执行
set -e

BIN_DIR="$1"
QCONF="$BIN_DIR/qconf"
WORK="${2:-${TMPDIR:-/tmp}/qconf-test-$$}"

if [ -z "$BIN_DIR" ] || [ ! -x "$QCONF" ]; then
    echo "FAIL: qconf binary not executable: $QCONF"
    exit 1
fi

PASS=0
FAIL=0
TOTAL=0

check() {
    TOTAL=$((TOTAL + 1))
    if [ "$1" = "1" ]; then
        PASS=$((PASS + 1))
        echo "  PASS  $2"
    else
        FAIL=$((FAIL + 1))
        echo "  FAIL  $2"
    fi
}

echo "=== qconf 2.5 test_package ==="
echo "bin_dir=$BIN_DIR"

rm -rf "$WORK"
mkdir -p "$WORK"
cd "$WORK"

# TC-01 --version
OUT="$(QCONF_REAL="$QCONF" "$QCONF" --version 2>&1 || true)"
case "$OUT" in
    *"qconf version"*) check 1 "TC-01-version" ;;
    *) echo "    got: $OUT"; check 0 "TC-01-version" ;;
esac

# TC-02 --help
OUT="$("$QCONF" --help 2>&1 || true)"
case "$OUT" in
    *"Usage: qconf"*) check 1 "TC-02-help" ;;
    *) echo "    got: $OUT"; check 0 "TC-02-help" ;;
esac

# 生成用的 .qc
echo '<qconf>' > sample.qc
echo '  <name>QConf Smoke Test</name>' >> sample.qc
echo '  <profile>sample.pro</profile>' >> sample.qc
echo '  <datadir/>' >> sample.qc
echo '</qconf>' >> sample.qc

# TC-03 生成 configure
OUT="$("$QCONF" sample.qc 2>&1 || true)"
if [ -f configure ]; then
    check 1 "TC-03-generate-configure"
else
    echo "    got: $OUT"
    check 0 "TC-03-generate-configure"
fi

# TC-04 生成标记
if grep -q "Generated by qconf" configure 2>/dev/null; then
    check 1 "TC-04-generated-marker"
else
    check 0 "TC-04-generated-marker"
fi

# TC-05 Qt5 conf4 运行期构建逻辑
if grep -q "conf4" configure 2>/dev/null; then
    check 1 "TC-05-embedded-conf4"
else
    check 0 "TC-05-embedded-conf4"
fi

# TC-06 【鸿蒙特有】OHOS aarch64 ELF（e_machine = 0xB7，小端字节序 b7 00）
MACHINE="$(od -An -tx1 -j18 -N2 "$QCONF" 2>/dev/null | tr -d ' \n')"
case "$MACHINE" in
    b700)
        if "$QCONF" --version >/dev/null 2>&1; then
            check 1 "TC-06-ohos-aarch64-elf-runs-on-device"
        else
            check 0 "TC-06-ohos-aarch64-elf-runs-on-device"
        fi
        ;;
    *)
        echo "    got e_machine=$MACHINE (expect b700)"
        check 0 "TC-06-ohos-aarch64-elf-runs-on-device"
        ;;
esac

echo "--------------------------------------------------------------"
echo "CASE SUMMARY: total=$TOTAL passed=$PASS failed=$FAIL skipped=0"
if [ "$FAIL" -ne 0 ]; then
    echo "RESULT: FAIL"
    exit 1
fi
echo "RESULT: PASS"
exit 0
